"""out/model.json -> ../studio-core/3_wheelchair_cadmodel.js
Emits CAD_MODEL (meshes, scenarios, kernel volumes) and cadPartDefs() for the unified wheelchair product file."""
import json
m = json.load(open('out/model.json', encoding='utf-8'))
seq = {pid: i for i, pid in enumerate(m['seq'])}
parts = sorted(m['parts'], key=lambda p: seq[p['id']])
for p in parts: p['vol'] = sum(i['vol'] for i in p['inst'])
js = [
 "/* ───────── CAD model data: CadQuery / OpenCascade B-rep (generated by wheelchair-cad/gen_js.py — do not edit) ───────── */",
 "const CAD_MODEL=" + json.dumps({'params': m['params'], 'materials': m['materials'], 'scenarios': m['scenarios'],
                                  'parts': parts}, ensure_ascii=False, separators=(',', ':')) + ";",
 """function decodeMesh(rec){const b=atob(rec.p),pb=new Uint8Array(b.length);for(let i=0;i<b.length;i++)pb[i]=b.charCodeAt(i);
  const c=atob(rec.i),ib=new Uint8Array(c.length);for(let i=0;i<c.length;i++)ib[i]=c.charCodeAt(i);
  const g=new THREE.BufferGeometry();g.setAttribute('position',new THREE.BufferAttribute(new Float32Array(pb.buffer),3));g.setIndex(new THREE.BufferAttribute(new Uint32Array(ib.buffer),1));g.computeVertexNormals();return g;}
function cadPartDefs(){return CAD_MODEL.parts.map(p=>({id:p.id,tool:p.tool,name:p.name,en:p.en,group:p.group,mat:p.mat,mb:p.mb,color:p.color,qty:p.qty,qtyInGeom:true,shell:p.shell,pieces:p.pieces,alt:p.alt,fastener:p.fastener,vol:p.vol,
  build:c=>({pos:V3(0,0,0),explode:V3(0,0,0),meshes:p.inst.map(m=>({g:decodeMesh(m),ex:m.ex,vol:m.vol}))})}));}""",
]
open('../studio-core/3_wheelchair_cadmodel.js', 'w', encoding='utf-8').write("\n".join(js) + "\n")
base = [p for p in parts if not p['alt']]
print(f"cadmodel js written: {sum(len(x) for x in js)/1e6:.1f} MB · baseline {len(base)} parts / {sum(p['pieces'] for p in base)} pieces · scenarios {len(m['scenarios'])}")
